// B-058 G13: what the Gemini, ElevenLabs and fal.ai adapters share around one exchange (generate-http.ts
// mediaExchange): the key header read when the call runs, the bounded wait for ONE provider job (the
// allowed exception to the no-polling rule: fal's queue and Gemini's generated files deliver only on
// request) – backoff from 0.5 s to 8 s, never past the call's deadline, cut by the run's stop –, the
// download of a result file a provider hands out by URL (at once: such links expire), the JSON parse of an
// answer and the file type of generated bytes. B-058 review: a paid job survives a passing failure – the wait
// rides out up to MAX_MISSES failed checks in a row (a network blip, a 5xx or 429 while the job runs), and a
// made result's fetch is asked once more – instead of losing (and on fal cancelling) the job.
// Owns: these steps and their user-safe errors (with the phase generate-http.ts defines). Never: logs or
// returns a key or a provider's raw body, sends a key to a result URL, or waits on more than the one job.

import { WorkforceError } from '../../../shared/errors.ts';
import { avMime, GENERATED_MAX_BYTES, generationPhase, imageMime, mediaExchange, reached, unusable, type GenerationPhase } from '../generate-http.ts';
import type { GenerationContext, GenerationKind, GenerationTarget } from './types.ts';

const FIRST_WAIT_MS = 500;
const MAX_WAIT_MS = 8_000;
const GROWTH = 1.6;
/** Failed checks in a row a job wait rides out. */
const MAX_MISSES = 3;
const RETRY_MS = 1_000;
const LOOPBACK = new Set(['localhost', '127.0.0.1', '[::1]', '::1']);

/**
 * A failed exchange worth asking again: it never reached an answer the provider meant (network, HTTP
 * status, rate limit) – not the deadline or the stop (they carry a phase), a broken answer (phase), a refused
 * request (bad_request) or the job's own end (adapters mark those with a phase).
 */
export function transient(error: unknown): boolean {
  return error instanceof WorkforceError && (error.code === 'unavailable' || error.code === 'rate_limited') && generationPhase(error) === undefined;
}

/** Runs `step`; a transient failure is asked once more after a short pause (within the deadline). */
export async function retryOnce<T>(ctx: GenerationContext, what: string, step: () => Promise<T>, phase: GenerationPhase = 'answered'): Promise<T> {
  try { return await step(); } catch (error) {
    if (!transient(error)) throw error;
    await pause(ctx, RETRY_MS, what, phase);
    return step();
  }
}

/** `{ [name]: prefix + key }` read in-process when the call runs; no saved key is a setup failure (nothing sent). */
export async function keyHeader(target: GenerationTarget, name: string, prefix = ''): Promise<Record<string, string>> {
  let key: string | undefined;
  try { key = await target.key?.(); } catch { key = undefined; }
  if (!key) throw unusable(`The ${target.account.label || target.account.provider} account has no saved key. Add it again in Settings › Models.`);
  return { [name]: `${prefix}${key}` };
}

/** Waits `ms`, at most until the call's deadline; the deadline or the run's stop ends the wait with an error at `phase`. */
export function pause(ctx: GenerationContext, ms: number, what: string, phase: GenerationPhase = 'sent'): Promise<void> {
  const left = ctx.deadlineMs - Date.now();
  if (ctx.signal?.aborted) return Promise.reject(new WorkforceError('cancelled', 'Stopped.', reached(phase)));
  if (left <= 0) return Promise.reject(new WorkforceError('timeout', `${what} took longer than the time allowed; the provider may still finish it.`, reached(phase)));
  return new Promise((resolve, reject) => {
    const done = () => { clearTimeout(timer); ctx.signal?.removeEventListener('abort', stop); };
    const stop = () => { done(); reject(new WorkforceError('cancelled', 'Stopped.', reached(phase))); };
    const timer = setTimeout(() => { done(); resolve(); }, Math.min(ms, left));
    (timer as { unref?: () => void }).unref?.();
    ctx.signal?.addEventListener('abort', stop, { once: true });
  });
}

/**
 * Asks `check` until it returns a value: the one job's state, with backoff, bounded by the deadline (then a
 * timeout at phase 'sent' – the job was accepted and may still be made and charged). Up to MAX_MISSES
 * transient failures in a row are ridden out; the next one (or any other) ends the wait.
 */
export async function waitForJob<T>(ctx: GenerationContext, what: string, check: () => Promise<T | undefined>): Promise<T> {
  let wait = FIRST_WAIT_MS;
  let misses = 0;
  for (;;) {
    let value: T | undefined;
    try {
      value = await check();
      misses = 0;
    } catch (error) {
      if (!transient(error) || ++misses > MAX_MISSES) throw error;
    }
    if (value !== undefined) return value;
    await pause(ctx, wait, what);
    wait = Math.min(MAX_WAIT_MS, Math.round(wait * GROWTH));
  }
}

/** A provider's result link: HTTPS, or plain HTTP on this PC only (local test servers). */
export function safeResultUrl(value: unknown): string | undefined {
  if (typeof value !== 'string' || value.length > 4096) return undefined;
  try {
    const url = new URL(value);
    if (url.username || url.password) return undefined;
    return url.protocol === 'https:' || (url.protocol === 'http:' && LOOPBACK.has(url.hostname)) ? url.href : undefined;
  } catch { return undefined; }
}

/** Same scheme, host and port: a URL a provider answered with that may carry the account's key. */
export function sameOrigin(url: string, base: string): boolean {
  try { return new URL(url).origin === new URL(base).origin; } catch { return false; }
}

/**
 * Downloads a generated file at once (provider links expire), without any key; every failure is at phase
 * 'answered' – the provider made and charged it.
 */
export async function downloadResult(ctx: GenerationContext, link: unknown, kind: GenerationKind, what: string, headers?: Record<string, string>): Promise<{ bytes: Buffer; type: string }> {
  const url = safeResultUrl(link);
  if (!url) throw new WorkforceError('unavailable', `${what} returned no usable file link.`, reached('answered'));
  try {
    const { raw, type } = await retryOnce(ctx, what, () => mediaExchange(ctx, { url, method: 'GET', headers, what, max: GENERATED_MAX_BYTES[kind], follow: true }));
    return { bytes: raw, type };
  } catch (error) {
    if (error instanceof WorkforceError && (error.code === 'timeout' || error.code === 'cancelled')) throw new WorkforceError(error.code, error.message, reached('answered'));
    throw new WorkforceError('unavailable', `${what} was made, but its file could not be downloaded (the link may have expired).`, reached('answered'));
  }
}

/** The JSON of an answer; anything else is a broken answer at `phase`. */
export function answerJson(raw: Buffer, what: string, phase: GenerationPhase = 'answered'): Record<string, unknown> {
  let parsed: unknown;
  try { parsed = JSON.parse(raw.toString('utf8')); } catch { parsed = undefined; }
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) throw new WorkforceError('unavailable', `${what} returned an invalid answer.`, reached(phase));
  return parsed as Record<string, unknown>;
}

const EXTENSION: Record<string, string> = {
  'image/png': 'png', 'image/jpeg': 'jpg', 'image/webp': 'webp', 'audio/mpeg': 'mp3', 'audio/wav': 'wav', 'audio/ogg': 'ogg', 'audio/flac': 'flac',
  'audio/mp4': 'm4a', 'audio/aac': 'aac', 'video/mp4': 'mp4', 'video/webm': 'webm', 'video/quicktime': 'mov',
};
const ALIASES: Record<string, string> = { 'audio/mp3': 'audio/mpeg', 'audio/x-wav': 'audio/wav', 'audio/wave': 'audio/wav', 'audio/m4a': 'audio/mp4', 'video/mov': 'video/quicktime' };

/** The file type of generated bytes: sniffed, else the declared type (normalized), with its extension. */
export function fileType(bytes: Uint8Array, declared: string | undefined, kind: GenerationKind): { mime: string; extension: string } {
  const named = declared ? declared.split(';')[0].trim().toLowerCase() : '';
  const sniffed = kind === 'image' ? imageMime(bytes) : avMime(bytes);
  let mime = sniffed ?? ALIASES[named] ?? named;
  if (kind !== 'video' && mime === 'video/mp4') mime = 'audio/mp4';
  if (!mime) mime = kind === 'image' ? 'image/png' : kind === 'video' ? 'video/mp4' : 'audio/mpeg';
  return { mime, extension: EXTENSION[mime] ?? (kind === 'image' ? 'png' : kind === 'video' ? 'mp4' : 'mp3') };
}

/** A short, safe excerpt of what a model said instead of making the file (a refusal, a question). */
export function modelSaid(text: string | undefined): string {
  const clean = (text ?? '').replace(/\s+/g, ' ').trim();
  return clean ? ` The model answered: "${clean.slice(0, 200)}${clean.length > 200 ? '…' : ''}"` : '';
}
